public class GameSimulator {
    public static void main(String[] args) {
        // Define the characters' personalities
        PersonalityType player1 = new PersonalityType("InDignation", "Violent");
        PersonalityType player2 = new PersonalityType("Peaceful", "Friendly");

        // Simulate the game scenario
        String simulationResult = simulateGame(player1, player2);
        System.out.println(simulationResult);
    }

    private static String simulateGame(PersonalityType player1, PersonalityType player2) {
        StringBuilder result = new StringBuilder();
        int turn = 1;

        while (turn <= 10) {
            if (player1 == player2) {
                result.append("Both players have the same type.");
            } else if (player1.equals("Violent")) {
                result.append("Player 1: Violent\n");
                result.append("Player 2: Friendly\n");
            } else if (player2.equals("Violent")) {
                result.append("Player 1: Friendly\n");
                result.append("Player 2: Violent\n");
            } else if (player1.equals("Friendly")) {
                result.append("Player 1: Friendly\n");
                result.append("Player 2: Friendly\n");
            } else if (player2.equals("Friendly")) {
                result.append("Player 1: Violent\n");
                result.append("Player 2: Violent\n");
            }
            turn++;
        }

        return result.toString();
    }

    static class PersonalityType {
        String type;
        String behavior;

        PersonalityType(String type, String behavior) {
            this.type = type;
            this.behavior = behavior;
        }
    }
}
